package slop

import (
	"encoding/json"
	"math"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// Golden differential tests against the committed oracle expectations in
// testdata/golden/. The goldens are generated by the pinned upstream
// JavaScript (testdata/upstream/runner.mjs via `make oracle`) in
// stage-1/fallback mode and are always exercised by ordinary `go test`;
// node is not required.

type oracleMatch struct {
	PatternName   string `json:"pattern_name"`
	Sentence      string `json:"sentence"`
	MatchText     string `json:"match_text"`
	SentenceCount int    `json:"sentence_count"`
}

type oracleResult struct {
	Name            string             `json:"name"`
	Chars           int                `json:"chars"`
	Tokens          int                `json:"tokens"`
	WordHits        [][2]any           `json:"word_hits"`
	TrigramHits     [][2]any           `json:"trigram_hits"`
	WordScore       float64            `json:"word_score_per_1k"`
	TrigramScore    float64            `json:"trigram_score_per_1k"`
	ContrastHits    int                `json:"contrast_hits"`
	ContrastRate    float64            `json:"contrast_rate_per_1k"`
	ContrastMatches []oracleMatch      `json:"contrast_matches"`
	Normalized      map[string]float64 `json:"normalized"`
	Score           float64            `json:"score"`
}

// debugAnalyze mirrors the oracle's computation using the same package
// primitives the public Analyze path uses.
func debugAnalyze(t *testing.T, a *Analyzer, text string) oracleResult {
	t.Helper()

	nTok := newNormText(text, quoteRune, true)
	toks := alphaTokens(wordsOnlyLower(nTok))

	nCon := newNormText(text, contrastRune, false)
	spans := sentenceSpans(nCon.runes)
	matches, err := a.detector.detect(nCon, spans)
	if err != nil {
		t.Fatalf("detect: %v", err)
	}

	out := oracleResult{Tokens: len(toks)}

	wordMap := map[string]int{}
	trigramMap := map[string]int{}
	if len(toks) > 0 {
		for _, tk := range toks {
			if _, ok := a.data.Words[tk.text]; ok {
				wordMap[tk.text]++
			}
		}
		for i := 0; i+3 <= len(toks); i++ {
			tri := toks[i].text + " " + toks[i+1].text + " " + toks[i+2].text
			if _, ok := a.data.Trigrams[tri]; ok {
				trigramMap[tri]++
			}
		}
	}
	wordTotal, trigramTotal := 0, 0
	for _, c := range wordMap {
		wordTotal += c
	}
	for _, c := range trigramMap {
		trigramTotal += c
	}
	for w, c := range wordMap {
		out.WordHits = append(out.WordHits, [2]any{w, c})
	}
	for w, c := range trigramMap {
		out.TrigramHits = append(out.TrigramHits, [2]any{w, c})
	}

	if len(toks) > 0 {
		out.WordScore = float64(wordTotal) / float64(len(toks)) * 1000
		out.TrigramScore = float64(trigramTotal) / float64(len(toks)) * 1000
	}
	chars := utf16Len(text)
	if chars > 0 {
		out.ContrastRate = float64(len(matches)) / float64(chars) * 1000
	}
	out.ContrastHits = len(matches)

	normTextStr := string(nCon.runes)
	for _, m := range matches {
		sentence := strings.TrimSpace(normTextStr[spans[m.sentLo][0]:spans[m.sentHi][1]])
		out.ContrastMatches = append(out.ContrastMatches, oracleMatch{
			PatternName:   m.pattern,
			Sentence:      sentence,
			MatchText:     m.matchText,
			SentenceCount: m.sentHi - m.sentLo + 1,
		})
	}

	nw := normalize(out.WordScore, a.data.WordRange)
	nt := normalize(out.TrigramScore, a.data.TrigramRange)
	nc := normalize(out.ContrastRate, a.data.ContrastRange)
	out.Normalized = map[string]float64{"words": nw, "trigrams": nt, "contrast": nc}
	out.Score = (nw*0.6 + nc*0.25 + nt*0.15) * 100
	return out
}

func loadGoldens(t *testing.T, path string) map[string]oracleResult {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read goldens %s: %v (regenerate with `make oracle`)", path, err)
	}
	var out map[string]oracleResult
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("parse goldens %s: %v", path, err)
	}
	return out
}

func hitMap(pairs [][2]any) map[string]int {
	out := map[string]int{}
	for _, p := range pairs {
		word, _ := p[0].(string)
		switch c := p[1].(type) {
		case int:
			out[word] = c
		case float64:
			out[word] = int(c)
		}
	}
	return out
}

func near(a, b float64) bool { return math.Abs(a-b) <= 1e-9 }

func compareToGolden(t *testing.T, got oracleResult, want oracleResult) {
	t.Helper()
	if got.Tokens != want.Tokens {
		t.Errorf("tokens: got %d, want %d", got.Tokens, want.Tokens)
	}
	if !near(got.WordScore, want.WordScore) {
		t.Errorf("word rate: got %v, want %v", got.WordScore, want.WordScore)
	}
	if !near(got.TrigramScore, want.TrigramScore) {
		t.Errorf("trigram rate: got %v, want %v", got.TrigramScore, want.TrigramScore)
	}
	if got.ContrastHits != want.ContrastHits {
		t.Errorf("contrast hits: got %d, want %d", got.ContrastHits, want.ContrastHits)
	}
	if !near(got.ContrastRate, want.ContrastRate) {
		t.Errorf("contrast rate: got %v, want %v", got.ContrastRate, want.ContrastRate)
	}

	gotWords, wantWords := hitMap(got.WordHits), hitMap(want.WordHits)
	if len(gotWords) != len(wantWords) {
		t.Errorf("word hit map size: got %d, want %d", len(gotWords), len(wantWords))
	}
	for w, c := range wantWords {
		if gotWords[w] != c {
			t.Errorf("word hit %q: got %d, want %d", w, gotWords[w], c)
		}
	}
	gotTri, wantTri := hitMap(got.TrigramHits), hitMap(want.TrigramHits)
	if len(gotTri) != len(wantTri) {
		t.Errorf("trigram hit map size: got %d, want %d", len(gotTri), len(wantTri))
	}
	for w, c := range wantTri {
		if gotTri[w] != c {
			t.Errorf("trigram hit %q: got %d, want %d", w, gotTri[w], c)
		}
	}

	if len(got.ContrastMatches) != len(want.ContrastMatches) {
		t.Fatalf("contrast matches: got %d, want %d", len(got.ContrastMatches), len(want.ContrastMatches))
	}
	for i, wm := range want.ContrastMatches {
		gm := got.ContrastMatches[i]
		if gm.PatternName != wm.PatternName {
			t.Errorf("match %d pattern: got %q, want %q", i, gm.PatternName, wm.PatternName)
		}
		if gm.MatchText != wm.MatchText {
			t.Errorf("match %d text:\n got  %q\n want %q", i, gm.MatchText, wm.MatchText)
		}
		if gm.SentenceCount != wm.SentenceCount {
			t.Errorf("match %d sentence count: got %d, want %d", i, gm.SentenceCount, wm.SentenceCount)
		}
		if gm.Sentence != wm.Sentence {
			t.Errorf("match %d sentence:\n got  %q\n want %q", i, gm.Sentence, wm.Sentence)
		}
	}

	for _, k := range []string{"words", "trigrams", "contrast"} {
		if !near(got.Normalized[k], want.Normalized[k]) {
			t.Errorf("normalized %s: got %v, want %v", k, got.Normalized[k], want.Normalized[k])
		}
	}
	if !near(got.Score, want.Score) {
		t.Errorf("score: got %v, want %v", got.Score, want.Score)
	}
}

// goldenInputPath resolves the runner-recorded path (relative to
// testdata/upstream) to a path readable from this package's test working
// directory.
func goldenInputPath(recorded string) string {
	clean := strings.TrimPrefix(recorded, "../")
	return filepath.Join("..", "testdata", clean)
}

func TestGoldenFixtures(t *testing.T) {
	a, err := NewAnalyzer()
	if err != nil {
		t.Fatal(err)
	}
	goldens := loadGoldens(t, filepath.Join("..", "testdata", "golden", "fixtures.json"))
	for name, want := range goldens {
		t.Run(filepath.Base(name), func(t *testing.T) {
			raw, err := os.ReadFile(goldenInputPath(name))
			if err != nil {
				t.Fatal(err)
			}
			got := debugAnalyze(t, a, string(raw))
			compareToGolden(t, got, want)

			// The public path must agree on the score value.
			doc, err := a.Analyze(name, string(raw), Options{})
			if err != nil {
				t.Fatal(err)
			}
			if doc.Score == nil {
				t.Fatal("public Analyze returned nil score for fixture")
			}
			if !near(doc.Score.Value, want.Score) {
				t.Errorf("public score: got %v, want %v", doc.Score.Value, want.Score)
			}
		})
	}
}

func TestGoldenCases(t *testing.T) {
	a, err := NewAnalyzer()
	if err != nil {
		t.Fatal(err)
	}
	goldens := loadGoldens(t, filepath.Join("..", "testdata", "golden", "cases.json"))
	for name, want := range goldens {
		t.Run(filepath.Base(name), func(t *testing.T) {
			raw, err := os.ReadFile(goldenInputPath(name))
			if err != nil {
				t.Fatal(err)
			}
			got := debugAnalyze(t, a, string(raw))
			compareToGolden(t, got, want)
		})
	}
}

// TestFixtureOrdering locks the regression signal from the original
// VellumFilter2 fixtures: scores must stay strictly ordered.
func TestFixtureOrdering(t *testing.T) {
	a, err := NewAnalyzer()
	if err != nil {
		t.Fatal(err)
	}
	var scores []float64
	names := []string{"sample2.txt", "sample1.txt", "sample4.txt", "sample3.txt", "sample5.txt"}
	for _, name := range names {
		raw, err := os.ReadFile(filepath.Join("..", "testdata", "fixtures", name))
		if err != nil {
			t.Fatal(err)
		}
		doc, err := a.Analyze(name, string(raw), Options{})
		if err != nil {
			t.Fatal(err)
		}
		if doc.Score == nil {
			t.Fatalf("nil score for %s", name)
		}
		scores = append(scores, doc.Score.Value)
	}
	for i := 1; i < len(scores); i++ {
		if scores[i] <= scores[i-1] {
			t.Errorf("ordering broken at %s: %v <= %v (want strictly increasing)", names[i], scores[i], scores[i-1])
		}
	}
}
